const config=window.APP_CONFIG||{},configured=!!(config.supabaseUrl&&config.supabaseKey);
let account=null,authSession=null,revision=null,cloudReady=false,syncTimer,syncQueue=Promise.resolve(),syncMessage='游客模式 · 记录仅在本机';
try{authSession=JSON.parse(localStorage.getItem('py-email-session'))}catch{}
const guestKey='py-helper-v1',blank=()=>({records:[],mistakes:{},session:null,plan:{daily:10,focus:'均衡学习',start:new Date().toISOString().slice(0,10)}});
function localKey(){return account?'py-user-'+account.id:guestKey}
const baseRender=render;
render=function(){baseRender();let header=document.querySelector('header');header.innerHTML=`<span>Python 易错点学习助手</span><div class="row"><span class="mini">${esc(syncMessage)}</span>${btn('我的计划',"go('plan')")}${account?btn('退出登录','signOut()'):btn('邮箱登录 / 注册',"go('account')")}</div>`;let nav=document.querySelector('#nav');nav.innerHTML+=`<a href="#plan" class="${page==='plan'?'active':''}">▦　我的学习计划</a>`;if(page==='plan')planPage();if(page==='account')accountPage()};
save=function(){try{localStorage.setItem(localKey(),JSON.stringify(db))}catch{syncMessage='本机存储失败，请检查浏览器设置'}if(account&&cloudReady){clearTimeout(syncTimer);syncTimer=setTimeout(()=>{syncQueue=syncQueue.then(syncCloud)},600)}};
async function api(path,options={}){let res=await fetch(config.supabaseUrl.replace(/\/$/,'')+path,{...options,headers:{apikey:config.supabaseKey,Authorization:'Bearer '+(authSession?.access_token||config.supabaseKey),'Content-Type':'application/json',...options.headers}});let body=await res.text();let data;try{data=JSON.parse(body)}catch{data=body}if(!res.ok)throw Error(data.msg||data.message||data.error_description||'服务暂时不可用，请重试');return data}
async function refreshAuth(){if(authSession&&Date.now()/1000>authSession.expires_at-60){let r=await api('/auth/v1/token?grant_type=refresh_token',{method:'POST',body:JSON.stringify({refresh_token:authSession.refresh_token})});authSession={...r,expires_at:r.expires_at||Date.now()/1000+r.expires_in};localStorage.setItem('py-email-session',JSON.stringify(authSession))}}
async function loadAccount(){await refreshAuth();let user=await api('/auth/v1/user');account=user;cloudReady=false;let rows=await api('/rest/v1/learning_state?select=data,revision&user_id=eq.'+encodeURIComponent(user.id));if(rows.length){db=rows[0].data;revision=rows[0].revision}else{db=blank();revision=null}cloudReady=true;syncMessage='已登录 · 云端进度';localStorage.setItem(localKey(),JSON.stringify(db));selection='';step=-1;render()}
async function syncCloud(){if(!account||!cloudReady)return;let snapshot=JSON.parse(JSON.stringify(db));try{await refreshAuth();let result=revision===null?await api('/rest/v1/learning_state',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify({user_id:account.id,data:snapshot,revision:1})}):await api('/rest/v1/learning_state?user_id=eq.'+account.id+'&revision=eq.'+revision,{method:'PATCH',headers:{Prefer:'return=representation'},body:JSON.stringify({data:snapshot,revision:revision+1})});if(!result.length){cloudReady=false;throw Error('另一台设备更新了记录。请先导出本机记录，再重新登录加载云端版本。')}revision=result[0].revision;syncMessage='云端已保存'}catch(e){syncMessage='同步未完成：'+e.message}let label=document.querySelector('header .mini');if(label)label.textContent=syncMessage}
function accountPage(){document.querySelector('#app').innerHTML=`<div class="sectiontop"><span class="eyebrow">YOUR OWN LEARNING SPACE</span><h1>每一份进步，都属于你。</h1><p>邮箱登录后，保存个人计划、练习记录和错题；游客记录保留在本机，不自动合并到账号。</p></div><section class="card" style="max-width:620px">${!configured?'<div class="notice">邮箱账号服务尚未配置。目前可使用游客练习与本机学习计划。站点管理员配置 Supabase 后即可启用注册和云端同步。</div>':''}<form onsubmit="event.preventDefault();authenticate(false)"><label>邮箱<br><input id="email" type="email" autocomplete="email" required style="width:100%;margin:10px 0 20px" placeholder="student@example.com"></label><label>密码（至少 8 位）<br><input id="password" type="password" minlength="8" autocomplete="current-password" required style="width:100%;margin:10px 0 20px"></label><div class="row"><button class="primary" ${configured?'':'disabled'}>登录</button><button type="button" onclick="authenticate(true)" ${configured?'':'disabled'}>注册新账号</button></div><p id="auth-message" role="status"></p></form><p class="mini">注册后请检查确认邮件，再返回此页登录。忘记密码时，可联系站点管理员通过账号服务发送重置邮件。</p></section>`}
async function authenticate(register){let email=document.querySelector('#email'),password=document.querySelector('#password'),msg=document.querySelector('#auth-message');if(!email.reportValidity()||!password.reportValidity())return;if(!configured)return;msg.textContent='正在连接账号服务…';try{let r=await api(register?'/auth/v1/signup':'/auth/v1/token?grant_type=password',{method:'POST',body:JSON.stringify({email:email.value.trim(),password:password.value})});password.value='';if(!r.access_token){msg.textContent='请检查邮箱中的确认邮件，验证后返回登录。';return}authSession={...r,expires_at:r.expires_at||Date.now()/1000+r.expires_in};localStorage.setItem('py-email-session',JSON.stringify(authSession));await loadAccount();go('plan')}catch(e){msg.textContent=e.message}}
async function signOut(){clearTimeout(syncTimer);await syncQueue;if(cloudReady)await syncCloud();try{await api('/auth/v1/logout',{method:'POST'})}catch{}account=null;authSession=null;cloudReady=false;localStorage.removeItem('py-email-session');try{db=JSON.parse(localStorage.getItem(guestKey))||blank()}catch{db=blank()}syncMessage='游客模式 · 记录仅在本机';go('home')}
function planPage(){let plan=db.plan||{daily:10,focus:'均衡学习'},today=new Date().toLocaleDateString('sv-SE'),done=db.records.filter(r=>new Date(r.time).toLocaleDateString('sv-SE')===today).length;document.querySelector('#app').innerHTML=`<div class="sectiontop"><span class="eyebrow">MY STUDY PLAN</span><h1>${account?'你的专属学习计划':'游客学习计划'}</h1><p>${account?esc(account.email):'当前计划保存在这台设备；配置账号服务并登录后可使用云端计划。'}</p></div><div class="grid"><article class="card"><p>今日作答 / 每日目标</p><div class="stats">${done} / ${plan.daily}</div><div class="bar"><div style="width:${Math.min(100,done/plan.daily*100)}%"></div></div></article><article class="card"><p>已练不同题目</p><div class="stats">${new Set(db.records.map(r=>r.id)).size} 道</div><p class="mini">题库无限，每轮按学习记录生成</p></article><article class="card"><p>到期复习</p><div class="stats">${due().length}</div>${btn('复习到期错题','start(null,due().map(m=>m.id))','wide',!due().length)}</article></div><section class="card"><h2>按自己的节奏来</h2><label>每天练习 <select id="daily">${[5,10,15,20].map(n=>`<option value="${n}" ${n===plan.daily?'selected':''}>${n} 题</option>`).join('')}</select></label>　<label>重点专项 <select id="focus">${['均衡学习',...cats].map(c=>`<option ${c===plan.focus?'selected':''}>${c}</option>`).join('')}</select></label><div class="row" style="margin-top:24px">${btn('保存计划','savePlan()','primary')}${btn('开始计划练习',`start('${plan.focus==='均衡学习'?recommendation().cat:plan.focus}')`)}</div><p>先完成到期复习，再做重点专项。每组 5 题，可连续练习至每日目标。</p></section><section class="card"><h3>最近 7 天</h3>${Array.from({length:7},(_,i)=>{let d=new Date();d.setDate(d.getDate()-6+i);let date=d.toLocaleDateString('sv-SE'),n=db.records.filter(r=>new Date(r.time).toLocaleDateString('sv-SE')===date).length;return `<div class="row listrow"><span>${date}</span><span>${n} 题</span></div>`}).join('')}</section>${btn('导出我的记录（JSON）','exportProgress()')}`}
function savePlan(){db.plan={daily:Number(document.querySelector('#daily').value),focus:document.querySelector('#focus').value,start:db.plan?.start||new Date().toISOString().slice(0,10)};save();planPage()}
function exportProgress(){let url=URL.createObjectURL(new Blob([JSON.stringify(db,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='python-learning-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
if(configured&&authSession)loadAccount().catch(e=>{syncMessage='登录恢复失败，请重新登录：'+e.message;account=null;cloudReady=false;render()});
